import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi } from 'vitest';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const availableBook: Book = {
  id: 'book-1',
  title: 'The Great Gatsby',
  author: 'F. Scott Fitzgerald',
  status: 'available',
};

const checkedOutBook: Book = {
  id: 'book-2',
  title: 'To Kill a Mockingbird',
  author: 'Harper Lee',
  status: 'checked-out',
};

describe('BookCard', () => {
  it('renders title', () => {
    render(<BookCard book={availableBook} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: 'The Great Gatsby' })).toBeInTheDocument();
  });

  it('renders author', () => {
    render(<BookCard book={availableBook} onClick={vi.fn()} />);
    expect(screen.getByText('F. Scott Fitzgerald')).toBeInTheDocument();
  });

  it('renders status badge with the book status text', () => {
    render(<BookCard book={availableBook} onClick={vi.fn()} />);
    expect(screen.getByText('available')).toBeInTheDocument();
  });

  it('sets data-status attribute on badge to reflect current status', () => {
    render(<BookCard book={checkedOutBook} onClick={vi.fn()} />);
    const badge = screen.getByText('checked-out');
    expect(badge).toHaveAttribute('data-status', 'checked-out');
  });

  it('sets aria-label combining title and author', () => {
    render(<BookCard book={availableBook} onClick={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' })
    ).toBeInTheDocument();
  });

  it('calls onClick with book id when clicked', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={availableBook} onClick={handleClick} />);
    await userEvent.click(screen.getByRole('button'));
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('book-1');
  });

  it('calls onClick with book id when Enter is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={availableBook} onClick={handleClick} />);
    screen.getByRole('button').focus();
    await userEvent.keyboard('{Enter}');
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('book-1');
  });

  it('does not call onClick when a key other than Enter is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={availableBook} onClick={handleClick} />);
    screen.getByRole('button').focus();
    await userEvent.keyboard('{Space}');
    expect(handleClick).not.toHaveBeenCalled();
  });
});

