const options = ['Fiction', 'Non-Fiction', 'Mystery'];

describe('ChipBar', () => {
  it('renders a chip for each option', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getAllByRole('button')).toHaveLength(3);
    expect(screen.getByRole('button', { name: 'Fiction' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Non-Fiction' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Mystery' })).toBeInTheDocument();
  });

  it('unselected chips have aria-pressed false', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Fiction' })).toHaveAttribute('aria-pressed', 'false');
    expect(screen.getByRole('button', { name: 'Mystery' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('selected chips have aria-pressed true', () => {
    render(<ChipBar options={options} selected={['Fiction']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Fiction' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'Mystery' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('calls onSelectionChange with the option added when an unselected chip is clicked', async () => {
    const handleChange = vi.fn();
    render(<ChipBar options={options} selected={[]} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(['Fiction']);
  });

  it('calls onSelectionChange without the option when a selected chip is clicked', async () => {
    const handleChange = vi.fn();
    render(<ChipBar options={options} selected={['Fiction']} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith([]);
  });

  it('preserves other selections when toggling one chip on', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar options={options} selected={['Mystery']} onSelectionChange={handleChange} />
    );
    await userEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(handleChange).toHaveBeenCalledWith(['Mystery', 'Fiction']);
  });

  it('preserves other selections when toggling one chip off', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar options={options} selected={['Fiction', 'Mystery']} onSelectionChange={handleChange} />
    );
    await userEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(handleChange).toHaveBeenCalledWith(['Mystery']);
  });
});

