import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import { useBooks } from './useBooks';
import * as api from '../api';

afterEach(() => {
  vi.restoreAllMocks();
});

describe('useBooks', () => {
  it('starts in loading state with null data and no error', async () => {
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
    await act(async () => {}); // flush pending promise to avoid act() warning
  });

  it('transitions to loaded state after getBooks resolves', async () => {
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.loading).toBe(false);
    expect(Array.isArray(result.current.data)).toBe(true);
    expect(result.current.error).toBeNull();
  });

  it('returned data matches getBooks output', async () => {
    const expected = await api.getBooks();
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.data).toEqual(expected);
  });

  it('sets error and clears loading when getBooks rejects', async () => {
    vi.spyOn(api, 'getBooks').mockRejectedValueOnce(new Error('load failed'));
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.loading).toBe(false);
    expect(result.current.error).toBeInstanceOf(Error);
    expect(result.current.error?.message).toBe('load failed');
    expect(result.current.data).toBeNull();
  });

  it('wraps non-Error rejections in an Error object', async () => {
    vi.spyOn(api, 'getBooks').mockRejectedValueOnce('string error');
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.error).toBeInstanceOf(Error);
    expect(result.current.error?.message).toBe('Unknown error');
    expect(result.current.loading).toBe(false);
  });
});

